#include "stdlib/stats/strided/snanmeankbn2.h"
#include "stdlib/blas/ext/base/snansumkbn2.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include <math.h>

/**
* Computes the arithmetic mean of a single-precision floating-point strided array, ignoring `NaN` values and using a second-order iterative Kahan–Babuška algorithm.
*
* ## Method
*
* -   This implementation uses a second-order iterative Kahan–Babuška algorithm, as described by Klein (2005).
*
* ## References
*
* -   Klein, Andreas. 2005. "A Generalized Kahan-Babuška-Summation-Algorithm." _Computing_ 76 (3): 279–93. doi:[10.1007/s00607-005-0139-x](https://doi.org/10.1007/s00607-005-0139-x).
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length
* @return         output value
*/
float API_SUFFIX(stdlib_strided_snanmeankbn2)( const CBLAS_INT N, const float *X, const CBLAS_INT strideX ) {
	const CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	return API_SUFFIX(stdlib_strided_snanmeankbn2_ndarray)( N, X, strideX, ox );
}

/**
* Computes the arithmetic mean of a single-precision floating-point strided array, ignoring `NaN` values and using a second-order iterative Kahan–Babuška algorithm with alternative indexing semantics.
*
* ## Method
*
* -   This implementation uses a second-order iterative Kahan–Babuška algorithm, as described by Klein (2005).
*
* ## References
*
* -   Klein, Andreas. 2005. "A Generalized Kahan-Babuška-Summation-Algorithm." _Computing_ 76 (3): 279–93. doi:[10.1007/s00607-005-0139-x](https://doi.org/10.1007/s00607-005-0139-x).
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length
* @param offsetX  starting index
* @return         output value
*/
float API_SUFFIX(stdlib_strided_snanmeankbn2_ndarray)( const CBLAS_INT N, const float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT i;
	CBLAS_INT ix;
	CBLAS_INT n;

	if ( N <= 0 ) {
		return 0.0f / 0.0f; // NaN
	}
	// Count non-NaN elements:
	n = 0;
	ix = offsetX;
	for ( i = 0; i < N; i++ ) {
		if ( !isnan( X[ ix ] ) ) {
			n += 1;
		}
		ix += strideX;
	}
	if ( n == 0 ) {
		return 0.0f / 0.0f; // NaN
	}
	return (double)API_SUFFIX(stdlib_strided_snansumkbn2_ndarray)( N, X, strideX, offsetX ) / (double)N;
}
